B.dfy=new A.q("subtitleColumn",B.v,"Node column shown as the card body/comment.",B.f,null)
B.djx=new A.q("orderColumn",B.v,"Numeric column the children sort by.",B.f,null)
B.d7p=new A.q("action",B.X,"Tap action spec { fn, args } \u2014 fired with the child rowId.",B.f,null)
B.dgL=new A.q("previewInline",B.W,"Opt-in: show an inline attachment PREVIEW in each card \u2014 image children as a thumbnail, previewable children with an Expand control. Off = the plain title+comment+chip card.",B.f,null)
