B.cPx=new A.d8("sidescroller","A real-time side-scrolling platformer with its own game loop (joystick + jump/attack); optional high-score persistence.",B.bnF,!1)
B.dgA=new A.q("cols",B.ah,"Grid columns (default 36).",B.f,null)
B.dgj=new A.q("rows",B.ah,"Grid rows (default 24).",B.f,null)
